arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Breaking change 1: HttpClientFactory now uses SocketsHttpHandler as the default
// primary handler. Casting to HttpClientHandler throws InvalidCastException.
// Fix: Use ConfigurePrimaryHttpMessageHandler with the desired handler type.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Breaking change 2: HttpClientFactory Trace-level logs now redact all header values
// by default. Allowlist specific non-sensitive headers needed for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Forwarded-For"
        && h != "X-Request-Id"
        && h != "Content-Type"));

// Breaking change 3: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers
// from proxies not in KnownProxies or KnownNetworks.
// Fix: Configure trusted proxy addresses for your environment.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownNetworks.Clear();
    options.KnownProxies.Clear();
    // TODO: Replace with your actual proxy addresses for production safety:
    // options.KnownProxies.Add(IPAddress.Parse("10.0.0.1"));
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

// Breaking change 4: ValidateOnBuild/ValidateScopes now enabled in development.
// The original code registered IUserService as Scoped but injected it into a
// Singleton (CacheService), which violates scope validation. Fixed above by
// changing ICacheService to Scoped.

// Breaking change 5: dotnet watch in .NET 9 SDK is incompatible with Hot Reload
// when targeting older frameworks. Since we now target net9.0, this is resolved.
// If you still need to target net8.0 for watch, use the .NET 8 SDK for that.

